import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Releases — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"releases-01-overview-and-concepts.md","filePath":"releases-01-overview-and-concepts.md"}'),o={name:"releases-01-overview-and-concepts.md"};function n(l,e,i,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="releases-—-overview-concepts" tabindex="-1">Releases — Overview &amp; Concepts <a class="header-anchor" href="#releases-—-overview-concepts" aria-label="Permalink to &quot;Releases — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-a-release" tabindex="-1">What Is a Release? <a class="header-anchor" href="#what-is-a-release" aria-label="Permalink to &quot;What Is a Release?&quot;">​</a></h2><p>A Release in Lodestone is a Kanban-style board populated with Features, used to communicate progress across the product development lifecycle. It answers the question stakeholders ask most often:</p><blockquote><p>&quot;How are things going — and when will it be done?&quot;</p></blockquote><p>Releases are communication artifacts, not delivery systems. They don&#39;t manage sprints, assign tickets, or replace tools like JIRA. They sit on top of execution and translate delivery status into a clear, shareable picture of progress.</p><hr><h2 id="releases-in-the-planning-stack" tabindex="-1">Releases in the Planning Stack <a class="header-anchor" href="#releases-in-the-planning-stack" aria-label="Permalink to &quot;Releases in the Planning Stack&quot;">​</a></h2><p>Lodestone&#39;s three core planning modules each answer a different question:</p><table tabindex="0"><thead><tr><th>Module</th><th>Answers</th></tr></thead><tbody><tr><td>Roadmaps</td><td>WHAT are we building, and WHY?</td></tr><tr><td><strong>Releases</strong></td><td><strong>WHEN is it happening, and how is progress tracking?</strong></td></tr><tr><td>Strategy</td><td>Where are we investing over the long term?</td></tr></tbody></table><p>Roadmaps define intent. Releases track execution against that intent over time.</p><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="the-kanban-board" tabindex="-1">The Kanban Board <a class="header-anchor" href="#the-kanban-board" aria-label="Permalink to &quot;The Kanban Board&quot;">​</a></h3><p>A Release is displayed as a Kanban board with columns representing status stages. Features appear as cards and move between columns as their status changes. The same status stages used across the platform (configured in Settings) apply here — Not Started, In Progress, Completed by default.</p><h3 id="status-as-a-single-source-of-truth" tabindex="-1">Status as a Single Source of Truth <a class="header-anchor" href="#status-as-a-single-source-of-truth" aria-label="Permalink to &quot;Status as a Single Source of Truth&quot;">​</a></h3><p>Moving a Feature card in a Release updates that Feature&#39;s status everywhere — the backlog, other Releases, and any other view. There is no separate Release-specific status. This means your Release board always reflects reality, and a status update in JIRA (via the integration) flows through to your Release automatically.</p><h3 id="actual-vs-forecast-mode" tabindex="-1">Actual vs Forecast Mode <a class="header-anchor" href="#actual-vs-forecast-mode" aria-label="Permalink to &quot;Actual vs Forecast Mode&quot;">​</a></h3><p>Every Release has two modes:</p><ul><li><strong>Actual</strong> — the real current state of Features based on their true status</li><li><strong>Forecast</strong> — a hypothetical projection where you can move Features forward to represent anticipated progress</li></ul><p>Forecast mode lets you communicate expected timelines and upcoming milestones without altering real data. Forecast changes are saved separately and persist until manually cleared — toggling back to Actual shows the real state, but your forecast positions are preserved for next time.</p><h3 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h3><p>Each Release includes a built-in Release Notes generator. Select the Features you want to include, choose an audience (internal or external), and Lodestone generates a tailored set of notes. Release Notes can be exported as a PDF or copied directly for use elsewhere. A single Release can produce multiple sets of notes — for example, one internal and one external — though regenerating overwrites the previous version.</p><hr><h2 id="how-releases-relate-to-the-rest-of-lodestone" tabindex="-1">How Releases Relate to the Rest of Lodestone <a class="header-anchor" href="#how-releases-relate-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Releases Relate to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Features</td><td>Features populate the Release board. A Feature can belong to multiple Releases. Removing a Feature from a Release doesn&#39;t affect the Feature itself.</td></tr><tr><td>Roadmaps</td><td>Releases can be created directly from a Roadmap, automatically pulling in all its Features. Roadmaps define intent; Releases track execution.</td></tr><tr><td>Settings</td><td>Status stages are configured globally in Settings and shared across all Releases.</td></tr><tr><td>Integrations</td><td>JIRA status changes sync into Lodestone and update Feature status on Release boards automatically.</td></tr><tr><td>Bento Grids</td><td>Release Notes from a Release can be used as the source for a Bento Grid — a visual, at-a-glance summary designed for stakeholder sharing.</td></tr></tbody></table><hr><h2 id="who-can-create-releases" tabindex="-1">Who Can Create Releases <a class="header-anchor" href="#who-can-create-releases" aria-label="Permalink to &quot;Who Can Create Releases&quot;">​</a></h2><p>Any workspace member can create a Release — it is not restricted to admins. A workspace can have multiple Releases running simultaneously, with no limit.</p><hr><h2 id="archiving-releases" tabindex="-1">Archiving Releases <a class="header-anchor" href="#archiving-releases" aria-label="Permalink to &quot;Archiving Releases&quot;">​</a></h2><p>Releases can be archived when they&#39;re no longer active. Archiving has no effect on the Features within it — they remain in the backlog and any other Releases they belong to. Archived Releases are removed from the active list but preserved for reference.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating, managing, and exporting Releases.</em></p>',35)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
